function shade(hex,p){ hex=String(hex).replace('#',''); if(hex.length===3) hex=hex.split('').map(function(c){return c+c;}).join('');
  var r=parseInt(hex.slice(0,2),16),g=parseInt(hex.slice(2,4),16),b=parseInt(hex.slice(4,6),16);
  var f=function(v){return ('0'+Math.max(0,Math.min(255,Math.round(v+(v*p/100)))).toString(16)).slice(-2);};
  return '#'+f(r)+f(g)+f(b); }
function btnCss(o){ o=o||{}; var bg=o.bg||'#5E6AD2', color=o.color||'#ffffff', r=o.radius==null?8:o.radius,
    py=o.paddingY==null?12:o.paddingY, px=o.paddingX==null?20:o.paddingX, fw=o.fontWeight||600,
    border=o.border||'none', shadow=o.shadow!==false, hover=o.hoverBg||shade(bg,-12);
  var s='.nano-btn{display:inline-block;background:'+bg+';color:'+color+';border-radius:'+r+'px;'+
    'padding:'+py+'px '+px+'px;font-weight:'+fw+';border:'+border+';cursor:pointer;'+
    (shadow?('box-shadow:0 6px 18px -10px '+bg+';'):'')+'}';
  s+='\n.nano-btn:hover{background:'+hover+';}'; return s; }
var EXPORTS={btnCss:btnCss, shade:shade};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
